const q = ($json.question || '').toLowerCase();
let normalizedDate = "day = '2026-01-02'";
let dateDesc = 'Bugün (2026-01-02)';
let requiresClarification = false;
let clarificationQuestion = null;

if (q.includes('bugün')) {
  normalizedDate = "day = '2026-01-02'";
  dateDesc = 'Bugün (2026-01-02)';
} else if (q.includes('dün')) {
  normalizedDate = "day = '2026-01-01'";
  dateDesc = 'Dün (2026-01-01)';
} else if (q.includes('bu hafta')) {
  normalizedDate = "day >= '2026-01-01' AND day <= '2026-01-07'";
  dateDesc = 'Bu hafta (2026-01-01 / 2026-01-07)';
} else if (q.includes('ocak') || q.includes('geçen ay')) {
  normalizedDate = "day >= '2026-01-01' AND day <= '2026-01-31'";
  dateDesc = 'Ocak 2026';
} else if (/\b\d{4}-\d{2}-\d{2}\b/.test(q)) {
  const m = q.match(/\b\d{4}-\d{2}-\d{2}\b/)[0];
  normalizedDate = `day = '${m}'`;
  dateDesc = m;
} else if (q === 'kim geç kaldı' || q === 'devamsızlar kim') {
  requiresClarification = true;
  clarificationQuestion = 'Hangi gün veya tarih aralığı için geç kalma/devamsızlık durumunu sorgulamak istersiniz? (Örn: Bugün, Dün, Bu hafta)';
}

return [{
  json: {
    question: $json.question,
    session_id: $json.session_id || 'sql_session',
    request_id: $json.request_id || ('req_' + Date.now()),
    normalizedDate,
    dateDesc,
    requiresClarification,
    clarificationQuestion
  }
}];

