const prev = $('Normalize Date and Entities').first().json;
const res = $json.message ? JSON.parse($json.message.content) : JSON.parse($json.response || '{}');

let rawSql = (res.sql || '').trim();
const forbidden = /\b(INSERT|UPDATE|DELETE|MERGE|DROP|ALTER|CREATE|TRUNCATE|COPY|CALL|GRANT|REVOKE|VACUUM|EXECUTE|PREPARE|DO)\b/i;
let isSafe = true;
let reason = '';

if (!/^\s*(WITH\s+[\s\S]+?\s+)?SELECT\s+/i.test(rawSql)) {
  isSafe = false;
  reason = 'Sorgu sadece SELECT ile başlamalıdır.';
} else if (forbidden.test(rawSql)) {
  isSafe = false;
  reason = 'Yasaklı DDL/DML anahtar kelimesi tespit edildi.';
} else if (rawSql.replace(/;+\s*$/, '').includes(';')) {
  isSafe = false;
  reason = 'Çoklu statement yasaktır.';
} else if (rawSql.includes('--') || rawSql.includes('/*')) {
  isSafe = false;
  reason = 'SQL yorum satırı yasaktır.';
}

if (isSafe && !rawSql.toLowerCase().includes('limit') && !rawSql.toLowerCase().includes('count(')) {
  rawSql = rawSql.replace(/;*$/, ' LIMIT 100;');
}

return [{
  json: {
    ...prev,
    sql: rawSql,
    isSafe,
    safetyReason: reason,
    intentSummary: res.intent_summary || ''
  }
}];

const items = $input.all().map(i => i.json);
const prev = $('SQL Safety Guard').first().json;

if (items.length === 0) {
  return [{
    json: {
      ...prev,
      status: 'SUCCESS',
      rowCount: 0,
      answer: `**Sorgu Özeti:**\n${prev.dateDesc} kapsamında aradığınız kriterlere uygun herhangi bir kayıt bulunamadı.\n\n*(Yürütülen SQL: \`${prev.sql}\`)*`,
      rows: []
    }
  }];
}

let summary = `**Sonuç Özeti (${prev.dateDesc}):**\nToplam **${items.length}** kayıt listelendi.\n\n`;
summary += '| Sicil | Ad Soyad | Departman | Durum | Detay |\n| :--- | :--- | :--- | :---: | :--- |\n';

for (const r of items.slice(0, 8)) {
  const empNo = r.employee_no || '-';
  const name = r.full_name || '-';
  const dept = r.department || '-';
  const status = r.status || '-';
  let detail = '';
  if (r.late_minutes && r.late_minutes > 0) detail = `${r.late_minutes} dk geç`;
  else if (r.worked_minutes) detail = `${r.worked_minutes} dk çalışma`;
  else if (r.exception_types) detail = r.exception_types;
  else if (r.missing_checkout) detail = 'Çıkış basılmadı';
  else detail = r.shift_name || '-';

  summary += `| ${empNo} | ${name} | ${dept} | **${status}** | ${detail} |\n`;
}

if (items.length > 8) {
  summary += `\n*... ve ${items.length - 8} kayıt daha.*`;
}
summary += `\n\n*(Yürütülen SQL: \`${prev.sql}\`)*`;

return [{
  json: {
    ...prev,
    status: 'SUCCESS',
    rowCount: items.length,
    answer: summary,
    rows: items
  }
}];
